```dart
class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, double> calculateAverageProfit(List<Transaction> transactions) {
  return transactions.reduce((map, transaction) {
    map[transaction.coinName] = (map[transaction.coinName] ?? 0) + transaction.profitLoss;
    return map;
  });
}

Map<String, double> calculateAverageLoss(List<Transaction> transactions) {
  return transactions.reduce((map, transaction) {
    map[transaction.coinName] = (map[transaction.coinName] ?? 0) - transaction.profitLoss;
    return map;
  });
}

List<dynamic> getTopCoins(List<Transaction> transactions, bool isProfit) {
  final averages = isProfit ? calculateAverageProfit : calculateAverageLoss;
  final averagesMap = averages(transactions);
  final sortedEntries = averagesMap.entries.toList()
      .where((entry) => entry.value != null) // Remove any null entries
      .orderBy((entry) => entry.value);

  return sortedEntries.take(isProfit ? 3 : 6).toList().reversed.take(3).toList();
}

