      return yourComparatorFunction(keyA, keyB);
    } else {
      return String.localeCompare(keyA, keyB, { sensitivity: 'base' }); // Default ascending order
    }
  });

  // Convert the sorted array back into a JSON object
  const sortedObj = Object.fromEntries(entries);

  return sortedObj;
}

// Usage example with default ascending order
