Next, create a Swift file named `HomophoneCorrector.swift` and paste the following code into it:

```swift
import Foundation
import NaturalLanguage

struct Homophone {
    let incorrect: String
    let correct: String
}

let homophones: [Homophone] = [
    ("their", "they're"),
    ("there", "there"),
    ("they're", "they are"),
    ("to", "too"),
    ("to", "two"),
    ("know", "no"),
    ("knot", "not"),
    ("weather", "whether"),
    ("right", "write")
]

func correctHomophones(in text: String) -> String {
    let tagger = NLTagger(tagSchemes: [.lemma])
    tagger.string = text

    var correctedText = ""
    tagger.enumerateTags(in: NSRange(text.startIndex..., in: text.endIndex), unit: .word, scheme: .lemma) { tag, range in
        guard let word = text[range], let lemma = tag?.rawValue else { return }

        let homophone = homophones.first(where: { $0.incorrect == word })
        if let homophone = homophone {
            correctedText += homophone.correct
        } else {
            correctedText += word
        }

        return true
    }

    return correctedText
}

