        "column_b": "new_column_name_for_B"
    },
    "TableB": {
        "column_x": "new_column_name_for_X",
        "column_y": "new_column_name_for_Y"
    }
}
```

3. Write a helper function to execute dynamic SQL queries.

```python
import psycopg2.extras as db_extra
from django.db import connection

def query_dynamic_table(model_name, columns):
    column_mapping = COLUMN_MAPPINGS[model_name]
    table_alias = "t"
    columns_str = ", ".join([f"{table_alias}.{col}" for col in columns])

    query = f"""
        SELECT {columns_str}
        FROM "{model_name}" AS {table_alias}
    """

    with connection.cursor(cursor_factory=db_extra.RealDictCursor) as cursor:
        cursor.execute(query)
        return cursor.fetchall()
```

